		((embeddedMode + 0x06) * seg3A6A->ActiveFontLineHeight_99BB + 0x07) >> 0x03;
	seg3A6A->GameOptionsMenuEntryCount_w0800 = embeddedMode + 0x06;
	seg3A6A->CampaignMenuRequested_bAEB8 = 0x00;

