// 1A1F:182E: void ScrollTacticalViewportToCursor_182E(void)
void ScrollTacticalViewportToCursor_182E(void)
{
	int16 cursorX = seg3A6A->TacticalCursorViewportX_8331;
	int16 cursorY = seg3A6A->TacticalCursorViewportY_8333;
	int16 viewportX = (int16) seg3A6A->TacticalViewportMapX_84A0;
	int16 viewportY = (int16) seg3A6A->TacticalViewportMapY_83DA;

	// V: keep the cursor in the 19x12 tactical viewport, scrolling the map
	// origin by the exact overflow and clamping it to the map bounds.
	if (cursorX < 0x00)
	{
		viewportX += cursorX;
		if (viewportX < 0x00)
			viewportX = 0x00;
		cursorX = 0x00;
	}
	if (cursorX >= 0x13)
	{
		viewportX += cursorX - 0x12;
		if (viewportX >= (int16) seg3A6A->MapWidth_00A6 - 0x13)
			viewportX = (int16) seg3A6A->MapWidth_00A6 - 0x13;
		cursorX = 0x12;
	}
	if (cursorY < 0x00)
	{
		viewportY += cursorY;
		if (viewportY < 0x00)
			viewportY = 0x00;
		cursorY = 0x00;
	}
	if (cursorY >= 0x0C)
	{
		viewportY += cursorY - 0x0B;
		if (viewportY >= (int16) seg3A6A->MapHeight_00A8 - 0x0C)
			viewportY = (int16) seg3A6A->MapHeight_00A8 - 0x0C;
		cursorY = 0x0B;
	}

	seg3A6A->TacticalCursorViewportX_8331 = cursorX;
	seg3A6A->TacticalCursorViewportY_8333 = cursorY;
	seg3A6A->TacticalViewportMapX_84A0 = (word16) viewportX;
	seg3A6A->TacticalViewportMapY_83DA = (word16) viewportY;
}

