		speedIndex = 0x07; // Keys 8 and 9 share the fastest setting.
	seg3A6A->TacticalUpdateDelayReloadTicks_17DA = updateDelayBySpeed[speedIndex];
	seg3A6A->TacticalGameSpeedIndex_17DC = speedIndex;
